(()=>{
const C=window.CM, $=s=>document.querySelector(s);let ui={query:'',spec:'all',fee:'all',clinic:'CL-001',step:1,slot:'',date:'2026-09-30',person:'',phone:'',note:'',lastId:''};
const clinic=id=>C.clinics.find(x=>x.id===id)||C.clinics[0];
const page=()=>location.hash.replace('#','').split('?')[0]||'home';
const nav=()=>{document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page()))};
function render(){nav();let s=C.load(),r=page();$('#main').innerHTML=({home:home,search:search,clinic:detail,book:book,confirmation:confirmation,portal:portal,states:states}[r]||home)(s);}
const art=()=>'<div class="clinic-art" aria-hidden="true"></div>';
const clinicCard=x=>`<article class="card clinic-card">${art()}<div><span class="pill ok">✓ Hồ sơ công khai đã duyệt · Mẫu</span><h3>${C.esc(x.name)}</h3><p>⌖ ${C.esc(x.address)} · ${x.branch}</p><p>${x.specialties.map(C.esc).join(' · ')}</p><p>Từ <strong>${C.money(x.fee)}</strong> / lượt khám (tham khảo)</p></div><div class="actions"><button class="btn" data-action="clinic" data-id="${x.id}">Xem phòng khám →</button></div></article>`;
function home(){return `<section class="hero"><div><div class="eyebrow">Chăm sóc sức khỏe, đơn giản hơn</div><h1>Tìm phòng khám phù hợp. Đặt lịch khám an tâm.</h1><p>Xem thông tin đã duyệt, chọn bác sĩ hoặc dịch vụ và theo dõi lịch hẹn tại một nơi. Hồ sơ và giá trong nguyên mẫu chỉ để minh họa.</p><form id="hero-search" class="searchbar"><input name="query" aria-label="Tìm phòng khám, bác sĩ hoặc chuyên khoa" placeholder="Bạn muốn khám ở đâu hoặc khám gì?" value="${C.esc(ui.query)}"><button class="btn" type="submit">⌕ Tìm phòng khám</button></form><div class="chip-row" style="margin-top:15px"><button class="chip" data-action="quick" data-query="Nội tổng quát">Nội tổng quát</button><button class="chip" data-action="quick" data-query="Nhi khoa">Nhi khoa</button><button class="chip" data-action="quick" data-query="Da liễu">Da liễu</button></div></div><div class="hero-visual" aria-hidden="true"><div class="hero-blob"></div><div class="doctor-ill"><div><div class="doctor-head"></div><div class="doctor-body"></div></div></div><div class="floating one">✓ Thông tin cơ sở được kiểm duyệt</div><div class="floating two">◷ Khung giờ rõ ràng · Đặt lịch thuận tiện</div></div></section><div class="grid three section"><div class="card feature"><div class="icon-bubble">⌕</div><h3>Tìm kiếm dễ dàng</h3><p>Tìm theo chuyên khoa, bác sĩ, dịch vụ và khu vực.</p></div><div class="card feature"><div class="icon-bubble">▦</div><h3>Chọn thời gian</h3><p>Khung giờ phải được xác minh lại lúc đặt chỗ.</p></div><div class="card feature"><div class="icon-bubble">▤</div><h3>Quản lý sau khám</h3><p>Theo dõi lịch, thanh toán và tài liệu đã công bố.</p></div></div><section class="section"><div class="section-head"><div><div class="eyebrow">Khám phá</div><h2>Phòng khám trên nền tảng</h2><p>Hồ sơ giả lập đã được gắn trạng thái công khai.</p></div><a class="btn secondary" href="#search">Xem tất cả →</a></div><div class="results">${C.clinics.filter(x=>x.verified).map(clinicCard).join('')}</div></section><section class="section notice">Đây là nguyên mẫu nghiên cứu UX. Các cơ sở, bác sĩ, số tiền và hồ sơ chỉ là dữ liệu mô phỏng; không dùng để tìm nơi khám thực tế.</section>`}
function search(){let q=ui.query.toLowerCase(),xs=C.clinics.filter(x=>x.verified).filter(x=>!q||[x.name,x.doctor,x.address,...x.specialties].join(' ').toLowerCase().includes(q)).filter(x=>ui.spec==='all'||x.specialties.includes(ui.spec)).filter(x=>ui.fee==='all'||x.fee<=Number(ui.fee));return `<div class="breadcrumbs"><a href="#home">Trang chủ</a> / Tìm phòng khám</div>${C.header('Tìm phòng khám','Lọc theo chuyên khoa, dịch vụ và chi phí khám tham khảo.')}<form id="search-form" class="card filters"><div><label for="q">Từ khóa</label><input id="q" name="query" value="${C.esc(ui.query)}" placeholder="Phòng khám, bác sĩ, chuyên khoa"></div><div><label for="spec">Chuyên khoa</label><select id="spec" name="spec"><option value="all">Tất cả chuyên khoa</option>${['Nội tổng quát','Nhi khoa','Da liễu','Tai Mũi Họng'].map(x=>`<option ${ui.spec===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label for="fee">Mức giá tham khảo</label><select id="fee" name="fee"><option value="all">Không giới hạn</option><option value="250000" ${ui.fee==='250000'?'selected':''}>Đến 250.000 ₫</option><option value="300000" ${ui.fee==='300000'?'selected':''}>Đến 300.000 ₫</option></select></div><button type="submit" class="btn">Áp dụng bộ lọc</button></form><div class="section-head section"><h2>${xs.length} kết quả phù hợp</h2><span class="pill ok">Chỉ hồ sơ được duyệt</span></div><div class="results">${xs.length?xs.map(clinicCard).join(''):`<div class="empty"><div class="icon-bubble">⌕</div><h3>Không tìm thấy kết quả</h3><p>Thử bỏ bớt bộ lọc hoặc tìm theo chuyên khoa khác.</p><button class="btn secondary" data-action="clear-filter">Xóa bộ lọc</button></div>`}</div>`}
function detail(){const x=clinic(ui.clinic);return `<div class="breadcrumbs"><a href="#search">Tìm phòng khám</a> / ${C.esc(x.name)}</div><div class="detail-top"><section class="card"><div class="eyebrow">HỒ SƠ ĐƯỢC DUYỆT · MÔ PHỎNG</div><h1 style="margin:12px 0">${C.esc(x.name)}</h1><span class="pill ok">✓ Được phép hiển thị công khai</span><p style="margin-top:16px">${C.esc(x.description)}</p><div class="info-row"><span>⌖</span><div><strong>Chi nhánh:</strong> ${C.esc(x.branch)}<br>${C.esc(x.address)}</div></div><div class="info-row"><span>◷</span><div><strong>Giờ hoạt động:</strong> ${C.esc(x.hours)}</div></div><div class="info-row"><span>▧</span><div><strong>Chuyên khoa:</strong> ${x.specialties.map(C.esc).join(', ')}</div></div><div class="notice">Thông tin giấy phép, chuyên môn và hồ sơ công khai phải được đối chiếu nguồn trong hệ thống thật. Ảnh, địa chỉ và bác sĩ ở đây là mẫu.</div></section><aside class="card sticky-summary"><div class="eyebrow">ĐẶT LỊCH KHÁM</div><h2 style="margin:10px 0">Chọn giờ khám thuận tiện</h2><p>Khám Nội tổng quát từ</p><div class="stat-value">${C.money(x.fee)}</div><p class="small">Giá tham khảo; phí phát sinh được hiển thị trước khi thu.</p><button class="btn full" data-action="book" data-id="${x.id}">Chọn giờ khám →</button></aside></div><section class="section card"><div class="section-head"><div><h2>Đội ngũ bác sĩ</h2><p>Hồ sơ đã được phép công bố trong demo.</p></div></div><div class="record"><div><span class="pill ok">Bác sĩ · Mô phỏng</span><h3 style="margin:8px 0">${C.esc(x.doctor)}</h3><p style="margin:0">Nội tổng quát · ${C.esc(x.branch)}</p></div><button class="btn secondary" data-action="book" data-id="${x.id}">Chọn lịch bác sĩ</button></div></section><section class="section card"><h2>Dịch vụ và bảng giá</h2><div class="service-row"><div><strong>Khám Nội tổng quát</strong><div class="muted small">Thời lượng dự kiến 30 phút · Giá minh họa</div></div><div class="price">${C.money(x.fee)}</div></div><div class="service-row"><div><strong>Xét nghiệm cơ bản</strong><div class="muted small">Chỉ thu khi có chỉ định hợp lệ</div></div><div class="price">Theo chỉ định</div></div></section>`}
function stepper(){return `<div class="stepper" aria-label="Các bước đặt lịch">${['1. Chọn lịch','2. Người khám','3. Kiểm tra','4. Xác nhận'].map((v,i)=>`<span class="step ${ui.step===i+1?'current':ui.step>i+1?'done':''}" ${ui.step===i+1?'aria-current="step"':''}>${v}</span>`).join('')}</div>`}
function book(s){const x=clinic(ui.clinic),used=s.appointments.filter(a=>a.clinicId===x.id&&a.date===ui.date&&a.status!=='canceled').map(a=>a.time),slots=['08:00','08:30','09:00','09:30','10:00','10:30','14:00','14:30'];const side=`<aside class="card sticky-summary"><div class="eyebrow">TÓM TẮT LỊCH</div><h3 style="margin:9px 0">${C.esc(x.name)}</h3><div class="summary-line"><span>Chi nhánh</span><strong>${C.esc(x.branch)}</strong></div><div class="summary-line"><span>Dịch vụ</span><strong>Khám Nội tổng quát</strong></div><div class="summary-line"><span>Bác sĩ</span><strong>${C.esc(x.doctor)}</strong></div><div class="summary-line"><span>Thời gian</span><strong>${C.date(ui.date)} ${ui.slot||'Chưa chọn'}</strong></div><hr><div class="summary-line"><span>Phí khám tham khảo</span><strong>${C.money(x.fee)}</strong></div><div class="notice warn">Chính sách đặt cọc và hoàn tiền đang chờ quyết định sản phẩm. Prototype không thu tiền.</div></aside>`;let body='';if(ui.step===1)body=`<form id="booking-slot" class="card"><h2>Chọn khung giờ</h2><div class="fields"><div><label for="service">Dịch vụ</label><select id="service"><option>Khám Nội tổng quát</option></select></div><div><label for="doctor">Bác sĩ</label><select id="doctor"><option>${C.esc(x.doctor)}</option></select></div><div><label for="date">Ngày khám</label><input id="date" name="date" type="date" min="2026-09-30" max="2026-10-15" value="${ui.date}"><div class="field-note">Ngày mẫu được cố định để chạy thử prototype.</div></div><div><label for="branch">Chi nhánh</label><select id="branch"><option>${C.esc(x.branch)}</option></select></div></div><fieldset class="section"><legend>Giờ còn trống (mô phỏng)</legend><div class="slots">${slots.map(t=>`<button type="button" class="slot ${ui.slot===t?'selected':''}" data-action="slot" data-time="${t}" ${used.includes(t)?'disabled aria-label="'+t+' đã được đặt"':''}>${t}${used.includes(t)?' · Hết':''}</button>`).join('')}</div><p class="small" style="margin-top:8px">Khung giờ có thể thay đổi. Hệ thống thật phải giữ và xác minh slot tại Appointment Service.</p></fieldset><div class="button-row section"><button class="btn" type="submit">Tiếp tục →</button><a class="btn secondary" href="#clinic">Quay lại</a></div></form>`;else if(ui.step===2)body=`<form id="booking-person" class="card"><h2>Thông tin người được khám</h2><p>Không dùng dữ liệu người thật; bạn có thể dùng tên mẫu mặc định.</p><div class="fields"><div><label for="patient-name">Họ tên người khám <span aria-hidden="true">*</span></label><input required id="patient-name" name="person" autocomplete="off" value="${C.esc(ui.person)}" placeholder="Ví dụ: Nguyễn An (mẫu)"></div><div><label for="patient-phone">Số liên hệ <span aria-hidden="true">*</span></label><input required id="patient-phone" name="phone" inputmode="tel" pattern="[0-9+ .()-]{9,18}" value="${C.esc(ui.phone)}" placeholder="0900 000 000"></div><div class="wide"><label for="patient-note">Lưu ý khi đến khám <span class="optional">(không bắt buộc)</span></label><textarea id="patient-note" name="note" placeholder="Không nhập dữ liệu sức khỏe thực trong prototype">${C.esc(ui.note)}</textarea></div></div><div class="button-row section"><button class="btn" type="submit">Xem lại lịch →</button><button type="button" class="btn secondary" data-action="back-step">← Quay lại</button></div></form>`;else body=`<div class="card"><h2>Kiểm tra trước khi đặt</h2><div class="summary-line"><span>Người khám</span><strong>${C.esc(ui.person)}</strong></div><div class="summary-line"><span>Liên hệ</span><strong>${C.esc(ui.phone)}</strong></div><div class="summary-line"><span>Giờ khám</span><strong>${C.date(ui.date)} · ${ui.slot}</strong></div><hr><div class="summary-line"><span>Phí khám tham khảo</span><strong>${C.money(x.fee)}</strong></div><div class="summary-line"><span>Thu ngay trên nguyên mẫu</span><strong>0 ₫</strong></div><div class="notice">Bản demo giả định không yêu cầu đặt cọc. Chính sách thanh toán, đổi/hủy lịch phải được phòng khám phê duyệt trước triển khai thật.</div><form id="booking-confirm" style="margin-top:20px"><label class="choice"><input id="accept" type="checkbox" required><span>Tôi đã xem thông tin lịch và lưu ý đây là thao tác mô phỏng.</span></label><div class="button-row section"><button class="btn" type="submit">Xác nhận lịch hẹn</button><button type="button" class="btn secondary" data-action="back-step">← Chỉnh sửa</button></div></form></div>`;return `<div class="breadcrumbs"><a href="#clinic">${C.esc(x.name)}</a> / Đặt lịch</div><h1>Đặt lịch khám</h1>${stepper()}<div class="booking-layout">${body}${side}</div>`}
function confirmation(s){const a=s.appointments.find(x=>x.id===ui.lastId);return a?`<div class="card" style="max-width:720px;margin:35px auto;text-align:center"><div class="icon-bubble" style="margin:auto">✓</div><div class="eyebrow" style="margin-top:18px">LỊCH HẸN DEMO ĐÃ ĐƯỢC TẠO</div><h1>Hẹn gặp bạn tại phòng khám</h1><p>Hãy dùng mã lịch hẹn khi đến quầy tiếp nhận. Trạng thái mô phỏng đã xác nhận; ứng dụng thật phải lấy kết quả từ Appointment Service.</p><div class="card flat" style="background:var(--canvas);text-align:left"><div class="summary-line"><span>Mã lịch hẹn</span><strong>${a.id}</strong></div><div class="summary-line"><span>Người khám</span><strong>${C.esc(a.patient)}</strong></div><div class="summary-line"><span>Ngày giờ</span><strong>${C.date(a.date)} ${a.time}</strong></div><div class="summary-line"><span>Trạng thái</span>${C.badge(a.status)}</div></div><div class="button-row" style="justify-content:center;margin-top:20px"><a class="btn" href="#portal">Xem lịch của tôi</a><a class="btn secondary" href="workspace.html#reception">Xem luồng lễ tân ↗</a></div></div>`:`<div class="empty"><h2>Chưa có lịch hẹn vừa tạo</h2><a class="btn" href="#search">Tìm phòng khám</a></div>`}
function portal(s){let tab=ui.portal||'appointments';let nav=['appointments','records','payments','dependents'];let labels=['Lịch hẹn','Tài liệu đã công bố','Thanh toán','Người thân'];let tabs=`<div class="tabs" role="tablist" aria-label="Patient portal">${nav.map((x,i)=>`<button role="tab" aria-selected="${tab===x}" class="tab ${tab===x?'active':''}" data-action="portal-tab" data-tab="${x}">${labels[i]}</button>`).join('')}</div>`;let body='';if(tab==='appointments')body=`<div class="records-list">${s.appointments.filter(a=>a.owned).map(a=>`<div class="record"><div><span class="pill progress">Mã lịch: ${a.id}</span><h3 style="margin:8px 0">${C.esc(a.patient)}</h3><div class="muted small">Phòng khám Đa khoa An Bình · ${C.date(a.date)} · ${a.time}</div><div class="small" style="margin-top:5px">${C.badge(a.status)}</div></div><div class="button-row">${a.status==='confirmed'?`<button class="btn secondary sm" data-action="cancel-appt" data-id="${a.id}">Yêu cầu hủy (demo)</button>`:''}<a href="workspace.html#reception" class="btn sm soft">Theo dõi tiếp nhận ↗</a></div></div>`).join('')}</div>`;if(tab==='records')body=`<div class="records-list">${s.visits.filter(v=>v.owned&&v.released&&v.signed).map(v=>`<div class="record"><div><span class="pill ok">Tài liệu được công bố</span><h3 style="margin:7px 0">Kết quả khám · ${v.id}</h3><div class="muted small">Nguồn: Phòng khám Đa khoa An Bình · Bác sĩ phụ trách: ${C.esc(v.doctor)}</div><div class="small">Chẩn đoán: ${C.esc(v.diagnosis||'Chưa ghi')} · Hướng dẫn: ${C.esc(v.prescription||'Chưa ghi')}</div></div><button class="btn secondary sm" data-action="view-record" data-id="${v.id}">Xem tóm tắt</button></div>`).join('')||`<div class="empty"><div class="icon-bubble">▤</div><h3>Chưa có tài liệu được công bố</h3><p>Không hiển thị bản nháp hoặc hồ sơ chưa được bác sĩ xác nhận và cho phép công bố.</p></div>`}</div>`;if(tab==='payments')body=`<div class="records-list">${s.visits.filter(v=>v.owned).map(v=>`<div class="record"><div><span class="pill progress">Mã lượt khám: ${v.id}</span><h3 style="margin:8px 0">Tổng chi phí mẫu: ${C.money(v.bill)}</h3><div class="small muted">Đã thu ${C.money(v.paid)} · Còn lại ${C.money(Math.max(0,v.bill-v.paid))}</div></div><a class="btn sm secondary" href="workspace.html#billing">Xem thu ngân demo ↗</a></div>`).join('')}</div>`;if(tab==='dependents')body=`<div class="notice warn"><strong>Quan hệ đại diện cần xác minh</strong><p style="margin:6px 0 0">Không tự thêm quyền xem bệnh án chỉ bằng việc nhập số điện thoại. Luồng xác minh người đại diện thuộc quyết định mở OD-10.</p></div><div class="empty section"><h3>Chưa có người thân được liên kết</h3><p>Thiết kế màn hình quản lý và thu hồi quyền sẽ được xác nhận cùng nhóm bảo vệ dữ liệu.</p></div>`;return `${C.header('Không gian bệnh nhân','Lịch khám, tài liệu đã công bố và các khoản thanh toán mô phỏng.','<span class="sample-label">DỮ LIỆU MẪU</span>')}<div class="card">${tabs}${body}</div>`}
function states(){return `${C.header('Thư viện trạng thái','Các trường hợp cần được thiết kế cho mọi màn hình.')}<div class="grid two"><div class="card"><span class="pill pending">Đang tải</span><h3>Đang lấy lịch khả dụng</h3><p>Giữ nguyên dữ liệu người dùng đã nhập. Hiển thị skeleton nếu thời gian tải dài.</p></div><div class="card"><span class="pill danger">Không có quyền</span><h3>Không thể xem hồ sơ</h3><p>Hãy chọn đúng cơ sở hoặc liên hệ quản trị viên; không tiết lộ dữ liệu từ cơ sở khác.</p></div><div class="card"><span class="pill pending">Cần thao tác lại</span><h3>Khung giờ vừa được đặt</h3><p>Quay lại chọn giờ; giữ nguyên thông tin liên hệ.</p></div><div class="card"><span class="pill progress">Đang xác minh</span><h3>Thanh toán chưa được đối soát</h3><p>Không hiển thị thành công từ redirect URL.</p></div></div>`}
function handle(e){let a=e.target.closest('[data-action]');if(!a)return;let act=a.dataset.action;if(act==='reset'){if(confirm('Đặt lại toàn bộ dữ liệu giả lập?')){C.reset();ui.lastId='';ui.step=1;location.hash='home';render();C.toast('Đã đặt lại dữ liệu mô phỏng.')}return;}if(act==='clinic'){ui.clinic=a.dataset.id;location.hash='clinic';}if(act==='book'){ui.clinic=a.dataset.id;ui.step=1;ui.slot='';location.hash='book';}if(act==='quick'){ui.query=a.dataset.query;location.hash='search';}if(act==='clear-filter'){ui.query='';ui.spec='all';ui.fee='all';render();}if(act==='slot'){ui.slot=a.dataset.time;render();}if(act==='back-step'){ui.step=Math.max(1,ui.step-1);render();}if(act==='portal-tab'){ui.portal=a.dataset.tab;render();}if(act==='cancel-appt'){let s=C.load(),o=s.appointments.find(x=>x.id===a.dataset.id);if(o&&confirm('Mô phỏng hủy lịch này? Chính sách hủy thực tế chưa được chốt.')){o.status='canceled';C.save(s);C.toast('Đã chuyển trạng thái hủy trong demo.');render();}}if(act==='view-record'){const v=C.load().visits.find(x=>x.id===a.dataset.id);if(v)alert(`BẢN TÓM TẮT ĐƯỢC CÔNG BỐ (MẪU)\n${v.id}\n${v.patient}\nChẩn đoán: ${v.diagnosis}\nDặn dò: ${v.prescription}`);}}
function submit(e){const f=e.target;if(!['hero-search','search-form','booking-slot','booking-person','booking-confirm'].includes(f.id))return;e.preventDefault();let d=new FormData(f);if(f.id==='hero-search'){ui.query=String(d.get('query')||'').trim();location.hash='search';render();}if(f.id==='search-form'){ui.query=String(d.get('query')||'').trim();ui.spec=d.get('spec');ui.fee=d.get('fee');render();}if(f.id==='booking-slot'){ui.date=d.get('date');if(!ui.slot){C.toast('Hãy chọn giờ khám còn trống.','error');return;}let s=C.load();if(s.appointments.some(a=>a.clinicId===ui.clinic&&a.date===ui.date&&a.time===ui.slot&&a.status!=='canceled')){ui.slot='';C.toast('Khung giờ vừa được đặt. Vui lòng chọn giờ khác.','error');render();return;}ui.step=2;render();}if(f.id==='booking-person'){ui.person=String(d.get('person')||'').trim();ui.phone=String(d.get('phone')||'').trim();ui.note=String(d.get('note')||'').trim();if(!ui.person||!ui.phone){C.toast('Vui lòng hoàn thành các trường bắt buộc.','error');return;}ui.step=3;render();}if(f.id==='booking-confirm'){let s=C.load();if(s.appointments.some(a=>a.clinicId===ui.clinic&&a.date===ui.date&&a.time===ui.slot&&a.status!=='canceled')){ui.step=1;ui.slot='';render();C.toast('Giờ khám đã thay đổi, hãy chọn slot khác.','error');return;}let id='LH-DEMO-'+String(s.seq++).padStart(3,'0'),x=clinic(ui.clinic);s.appointments.push({id,patientCode:'BN-DEMO-'+String(s.seq).padStart(3,'0'),patient:ui.person,phone:ui.phone,clinicId:x.id,branch:x.id==='CL-001'?'BR-001':'BR-003',doctor:x.doctor,service:'Khám Nội tổng quát',date:ui.date,time:ui.slot,status:'confirmed',deposit:0,fee:x.fee,owned:true});C.save(s);ui.lastId=id;ui.step=4;location.hash='confirmation';render();}}
document.addEventListener('click',handle);document.addEventListener('submit',submit);document.addEventListener('change',e=>{if(e.target.id==='date'){ui.date=e.target.value;ui.slot='';render()}});window.addEventListener('hashchange',render);window.addEventListener('demochange',render);render();
})();
